void dei_rf1_tx_frame(UInt8 cmd)	  
{    
	CRITICAL;
	
	C_ENTER;
	{
		OUT_TX_RF( FALSE ) ; // RF OFF

		dei_rf1_vars.tx_data      = ((dei_rf1_vars.hhu_sn_used<<8)&0xFFFFFF00)|((UInt32)cmd&0x000000FF);
		dei_rf1_vars.tx_copy_data = dei_rf1_vars.tx_data ; 
		
		dei_rf1_vars.tx_idx = 0;
		dei_rf1_vars.tx_complete     = FALSE ; 
		dei_rf1_vars.tx_in_progress  = TRUE  ;
		dei_rf1_vars.tx_bit_complete = FALSE ;
		dei_rf1_vars.tx_frame_count  = DEI_RF1_TX_FRAME_MAX ;
		
		tmr_irq_dis   ( dei_rf1_vars.tx_tmr );
		tmr_irq_update( dei_rf1_vars.tx_tmr , DEI_RF1_TX_FIRST_FRAME_TIMEOUT , FALSE );		
		tmr_irq_ena   ( dei_rf1_vars.tx_tmr ); 
	}
	C_LEAVE;      
} 


